    58  static int
    59  _isNFC (uint32_t * label, size_t len)
    60  {
    61    int lastCanonicalClass = 0;
    62    int result = 1;
    63    size_t it;
    64
    65    for (it = 0; it < len; it++)
    66      {
    67        uint32_t ch = label[it];
    68
    69        // supplementary code point
    70        if (ch >= 0x10000)
    71          it++;
    72
    73        int canonicalClass = uc_combining_class (ch);
    74        if (lastCanonicalClass > canonicalClass && canonicalClass != 0)
    75          return 0;
    76
    77        NFCQCMap *map = get_nfcqc_map (ch);
    78        if (map)
    79          {
    80            if (map->check)
    81              return 0;
    82            result = -1;
    83          }
    84
    85        lastCanonicalClass = canonicalClass;
    86      }
    87
    88    return result;
    89  }
